        <script>
        (function(){
            const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
            const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];

            /* run a loop only while its element is on screen */
            function whileVisible(el,tick){let on=false,raf=0,last=0;
            function loop(now){if(!on)return;const dt=Math.min(.05,(now-(last||now))/1000);last=now;tick(dt,now/1000);raf=requestAnimationFrame(loop);}
            new IntersectionObserver(es=>{const v=es[0].isIntersecting;if(v&&!on){on=true;last=0;raf=requestAnimationFrame(loop);}else if(!v){on=false;cancelAnimationFrame(raf);}}).observe(el);
            return {kick(){if(!on)tick(0,performance.now()/1000);}};}

            /* quiet star fields on the 2D sections, drawn while in view and clear of the copy */
            function field(cv,n,sel){const ctx=cv.getContext('2d');let w=0,h=0,S=[],t=0;
            function size(){const r=cv.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,1.5);w=r.width;h=r.height;cv.width=w*d;cv.height=h*d;ctx.setTransform(d,0,0,d,0,0);
                const host=cv.parentNode,hr=host.getBoundingClientRect(),pad=14;
                const X=$$(sel,host).map(e=>{const q=e.getBoundingClientRect();return [q.left-hr.left-pad,q.top-hr.top-pad,q.right-hr.left+pad,q.bottom-hr.top+pad];});
                const dn=host.querySelector('.dn'),top=dn?dn.getBoundingClientRect().top-hr.top:h+1;
                let s=7;const R=()=>(s=(s*16807)%2147483647)/2147483647;S=[];for(let i=0;i<n*(w*h)/1.6e6;i++){const x=R()*w,y=R()*h,r=R()<.06?1.4:.4+R()*.7,p=R()*6,tw=R()<.7;if(y>top)continue;if(X.some(b=>x>b[0]&&x<b[2]&&y>b[1]&&y<b[3]))continue;S.push([x,y,r,p,tw]);}draw();}
            function draw(){ctx.clearRect(0,0,w,h);S.forEach(([x,y,r,p,tw])=>{const a=tw&&!RM?.38+.5*Math.sin(t*(1.3+p*.3)+p*9):.55;ctx.fillStyle='rgba(225,245,250,'+a.toFixed(3)+')';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();});}
            whileVisible(cv,(dt)=>{t+=dt;draw();});addEventListener('resize',size);size();setTimeout(size,1200);return {size};}

            const F=[field($('.ft canvas.sk'),1100,'p,ul,.lg,.bot,h4')];
        })();
</script>
